source.exploreUrl:
@js:
var url=source.key,
html=java.ajax(url);
a=org.jsoup.Jsoup.parse(html)
.select("nav.nav li:gt(0):lt(11) a");
var arr=[],sort=[];
if(html&&a){
	arr=Array.from(a, x=>[
		x.text(),String(x.attr("href"))
		.replace(/1/,"{{page}}")
		.replace(/quanben.+(?!1).?$/,
			"$&<,{{page}}/>")] );
		sort=arr.map(([title,link])=>({
    "title": title,
    "url": link,
    "style": {
      "layout_flexGrow": 1,
       "layout_flexBasisPercent": 0.2
    }
  }));

  JSON.stringify(sort)

	}else java.toast("发现列表获取失败！")

ruleSearch.bookList:
@js:
var list=[];
var bookSound=baseUrl.match(/(.*?\/\/.*?)\//)[1];//? 非贪婪
if(result.indexOf("<script>alert")!=-1){
	//搜索出现问题,总会有问题的.软件默认一次搜索进行多次.网站规定30秒搜索1次
}else{
	var data=result.match(/container flex flex-wrap mb20([^@]*)container"/)[1];
	var dataList=data.split("category-div");
	for(var i=1,len=dataList.length;i<len;i++){
		var temp=dataList[i].match(/flex flex-between commend-title"><a href="(.*)"><h3>([^@]*)<\/h3>.*<span>([^@]*)<\/span>[^@]*"intro indent">([^@]*?)<\/div>/);
		list.push({
			"name":temp[2],
			"author":temp[3],
			"intro":temp[4],
			"bookUrl":bookSound+temp[1]
		});
	}
}
list;

